 * order, trailing newline) is preserved untouched.
 */
export function applyVersionToContent(
  content: string,
  isJson: boolean,
  newVersion: string,
): string {
  if (!isJson) {
    return `${newVersion}\n`;
  }
  if (!PACKAGE_VERSION_RE.test(content)) {
    throw new Error('JSON version file has no "version" field to update.');
  }
  return content.replace(PACKAGE_VERSION_RE, `$1${newVersion}$3`);
