  test("groups breaking/feat/fix commits into the expected sections", () => {
    const commits = parseCommitLog(
      [
        "feat(auth): add login page",
        "--- COMMIT ---",
        "fix(api): handle null response",
        "--- COMMIT ---",
        "feat!: drop v1 config\n\nBREAKING CHANGE: removed",
